// Generates public/icons.json: every image under public/images/, in a stable order. The service
// worker downloads the listed icons in the background after launch, so every screen's artwork is
// available offline before a game starts. Adding an image to public/images/ is enough: the next
// build picks it up automatically.
//
// The manifest is a build artifact: it is git-ignored and regenerated by the npm pre-hooks of
// start, build and test, so branches never conflict on it.
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const publicDir = path.join(root, "public");
const imagesDir = path.join(publicDir, "images");
const output = path.join(publicDir, "icons.json");

function filesUnder(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const relative = path.join(directory, entry.name);
    return entry.isDirectory() ? filesUnder(relative) : [relative];
  });
}

const urls = filesUnder(imagesDir)
  .map((file) => "/" + path.relative(publicDir, file).split(path.sep).join("/"))
  .sort();

const serialized = `${JSON.stringify(urls, null, 2)}\n`;
// Skip an identical rewrite so parallel scripts never read a half-written file or churn mtimes.
const current = fs.existsSync(output) ? fs.readFileSync(output, "utf8") : "";
if (current !== serialized) {
  fs.writeFileSync(output, serialized);
}
